//! Cross-language test vectors. These are generated by
//! `vanta/tools/make-vectors.mjs` and MUST fail if either implementation
//! diverges by a single byte.

use serde_json::Value;
use vanta::aead::{SealKey, DETERMINISTIC_OVERHEAD, OVERHEAD};
use vanta::padme::padme;

fn vectors() -> Value {
    let text = include_str!("../../vanta/vectors/vanta-vectors.json");
    serde_json::from_str(text).expect("vectors.json parses")
}

fn bytes(v: &Value, key: &str) -> Vec<u8> {
    hex::decode(v[key].as_str().expect("hex field")).expect("valid hex")
}

#[test]
fn aead_matches_javascript_byte_for_byte() {
    let v = vectors();
    let key = hex::decode(v["aead"]["keyHex"].as_str().unwrap()).unwrap();
    let seal = SealKey::new(&key).unwrap();
    for case in v["aead"]["cases"].as_array().unwrap() {
        let pt = bytes(case, "plaintextHex");
        let aad = bytes(case, "aadHex");
        let nonce: [u8; 16] = bytes(case, "nonceHex").try_into().unwrap();
        let expected = bytes(case, "probabilisticHex");
        let got = seal.seal(&pt, &aad, Some(nonce)).unwrap();
        assert_eq!(got, expected, "probabilistic vector mismatch");
        assert_eq!(got.len(), pt.len() + OVERHEAD);

        let det = seal.seal(&pt, &aad, None).unwrap();
        assert_eq!(det, bytes(case, "deterministicHex"), "deterministic mismatch");
        assert_eq!(det.len(), pt.len() + DETERMINISTIC_OVERHEAD);

        assert_eq!(seal.open(&got, &aad, false).unwrap(), pt);
        assert_eq!(seal.open(&det, &aad, true).unwrap(), pt);
    }
}

#[test]
fn padme_matches_javascript() {
    let v = vectors();
    for case in v["padme"].as_array().unwrap() {
        let len = case["length"].as_u64().unwrap() as usize;
        let max = case["max"].as_u64().unwrap() as usize;
        let want = case["padded"].as_u64().unwrap() as usize;
        assert_eq!(padme(len, max).unwrap(), want, "padme({len},{max})");
    }
}

#[test]
fn shamir_matches_javascript() {
    let v = vectors();
    let secret = hex::decode(v["shamir"]["secretHex"].as_str().unwrap()).unwrap();
    let shares: Vec<Vec<u8>> = v["shamir"]["sharesHex"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| hex::decode(s.as_str().unwrap()).unwrap())
        .collect();
    let k = v["shamir"]["threshold"].as_u64().unwrap() as usize;
    assert_eq!(vanta::guard::shamir_combine(&shares[..k]).unwrap(), secret);
    assert_eq!(
        vanta::guard::shamir_combine(&[shares[0].clone(), shares[2].clone(), shares[4].clone()])
            .unwrap(),
        secret
    );
}

#[test]
fn kem_decapsulates_javascript_ciphertext() {
    let v = vectors();
    let sk = bytes(&v["kem"], "secretKeyHex");
    let ct = bytes(&v["kem"], "cipherTextHex");
    let want = bytes(&v["kem"], "sharedSecretHex");
    let got = vanta::xwing::decapsulate(&ct, &sk).unwrap();
    assert_eq!(hex::encode(got), hex::encode(want));
}

#[test]
fn envelope_overhead_constant() {
    let v = vectors();
    for case in v["aead"]["cases"].as_array().unwrap() {
        let pt = bytes(case, "plaintextHex");
        let env = bytes(case, "probabilisticHex");
        assert_eq!(env.len(), pt.len() + 80);
    }
}
